import React from 'react';
export default function Header({CityName}, {Temperature}, {HighTemp}, {LowTemp}, {Description}){
    return (
        <div>
            <h1>{CityName}</h1>
            <p>{Temperature}</p>
            <p>{Description}</p>
            <p> H:{HighTemp}  L:{LowTemp}</p>
        </div>
    )

};
